# rearranging the columns:

# CELL ********************

audible_cleaned = df9.select("AudiobookId", "BookName", "PrimaryAuthor", "DurationMinutes", "ReleaseDate", "Language", "Price", "Rating", "NoOfRatings")

display(audible_cleaned)

